pub fn find(path: []const u8) ?*const Spec { for (&SPECS) |*sp| { if (sp.pre) { if (std.mem.startsWith(u8, path, sp.path)) return sp; } else if (std.mem.eql(u8, path, sp.path)) return sp; } return null; }
const HEAD = "<!DOCTYPE html><html><head><meta charset=\"utf-8\"><title>fixture</title></head><body><script>function rec(k,t){fetch('/_rec?k='+k+'&t='+encodeURIComponent(t))}function vals(){return Array.from(document.querySelectorAll('[data-box]')).map(function(b){return b.innerText||''}).join('|')}function act(b){var l=b.getAttribute('aria-label');rec('btn',l+'|'+vals());var o=b.getAttribute('data-out');var p=document.createElement('p');p.textContent=o||('Done: '+l);document.body.appendChild(p)}function item(b){var l=b.getAttribute('aria-label');rec('item',l+'@'+b.parentNode.getAttribute('aria-label'));b.parentNode.remove()}document.addEventListener('keydown',function(e){var t=e.target;if(e.key==='Enter'&&t.getAttribute&&t.getAttribute('data-box')){e.preventDefault();var x=t.innerText.trim();rec('key',t.getAttribute('aria-label')+'='+x);var p=document.createElement('p');p.textContent=x;document.body.appendChild(p)}})</script>";
fn put(out: *std.ArrayList(u8), allo: std.mem.Allocator, comptime fmtz: []const u8, args: anytype) !void { const txt = try std.fmt.allocPrint(allo, fmtz, args); defer allo.free(txt); try out.appendSlice(allo, txt); }
pub fn render(allo: std.mem.Allocator, sp: *const Spec) ![]u8 { var out: std.ArrayList(u8) = .empty; errdefer out.deinit(allo); try out.appendSlice(allo, HEAD); try put(&out, allo, "<h1>{s}</h1>", .{sp.title}); if (sp.popup) try out.appendSlice(allo, "<div role=\"dialog\" id=\"pp\"><p>Welcome</p><div role=\"button\" tabindex=\"0\" aria-label=\"Not now\" onclick=\"document.getElementById('pp').remove();rec('popup','closed')\">Not now</div></div>"); for (sp.btns) |raw| { const cut = std.mem.find(u8, raw, "=>"); const lab = if (cut) |ix| raw[0..ix] else raw; const res = if (cut) |ix| raw[ix + 2 ..] else ""; try put(&out, allo, "<div role=\"button\" tabindex=\"0\" aria-label=\"{s}\" data-out=\"{s}\" onclick=\"act(this)\">{s}</div>", .{ lab, res, lab }); } for (sp.boxes) |bx| try put(&out, allo, "<div role=\"textbox\" contenteditable=\"true\" data-box=\"1\" aria-label=\"{s}\">{s}</div>", .{ bx.lab, bx.init }); for (sp.combos) |cb| { try put(&out, allo, "<div role=\"combobox\" tabindex=\"0\" aria-label=\"{s}\" aria-expanded=\"false\" onclick=\"this.nextElementSibling.hidden=false\">{s}</div><div hidden>", .{ cb.lab, cb.lab }); for (cb.opts) |op| try put(&out, allo, "<div role=\"option\" tabindex=\"0\" aria-label=\"{s}\" onclick=\"rec('opt',this.parentNode.previousElementSibling.getAttribute('aria-label')+'='+this.getAttribute('aria-label'));this.parentNode.hidden=true\">{s}</div>", .{ op, op }); try out.appendSlice(allo, "</div>"); } for (sp.togs) |tg| try put(&out, allo, "<div role=\"checkbox\" tabindex=\"0\" aria-checked=\"false\" aria-label=\"{s}\" onclick=\"var on=this.getAttribute('aria-checked')!=='true';this.setAttribute('aria-checked',on);rec('tog',this.getAttribute('aria-label')+'='+(on?'on':'off'))\">{s}</div>", .{ tg, tg }); for (sp.hovs) |hv| { try put(&out, allo, "<div onmouseenter=\"this.lastElementChild.hidden=false\"><div role=\"button\" tabindex=\"0\" aria-label=\"{s}\">{s}</div><div hidden>", .{ hv.lab, hv.lab }); for (hv.items) |it| try put(&out, allo, "<div role=\"menuitem\" tabindex=\"0\" aria-label=\"{s}\" onclick=\"rec('hov','{s}>{s}')\">{s}</div>", .{ it, hv.lab, it, it }); try out.appendSlice(allo, "</div></div>"); } for (sp.items) |im| { try put(&out, allo, "<div role=\"article\" aria-label=\"{s}\"><span>{s}</span>", .{ im.name, im.name }); if (im.box.len > 0) try put(&out, allo, "<div role=\"textbox\" contenteditable=\"true\" data-box=\"1\" aria-label=\"{s}\"></div>", .{im.box}); for (im.btns) |lab| try put(&out, allo, "<div role=\"button\" tabindex=\"0\" aria-label=\"{s}\" onclick=\"item(this)\">{s}</div>", .{ lab, lab }); try out.appendSlice(allo, "</div>"); } for (sp.links) |lk| try put(&out, allo, "<a href=\"{s}\" aria-label=\"{s}\">{s}</a>", .{ lk.href, lk.lab, lk.text }); if (sp.file) try out.appendSlice(allo, "<input type=\"file\" aria-label=\"Upload\" onchange=\"rec('file',this.files.length)\">"); try out.appendSlice(allo, "</body></html>"); return out.toOwnedSlice(allo); }
